// BookDeleteOne builds the delete of one `books` row. Start one with
// `Graph.books().delete_one(node)` or `delete_one_id(id)`.
pub struct BookDeleteOne {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete_one starts the delete of the row of `node`.
pub fn (q BookQuery) delete_one(node BookNode) BookDeleteOne {
	return q.delete_one_id(node.book.id)
}

// delete_one_id starts the delete of the row with the key `id`.
pub fn (q BookQuery) delete_one_id(id int) BookDeleteOne {
	return BookDeleteOne{
		graph: q.graph
		data:  vgraph.MutationData{
			op:      .delete_one
			table:   'books'
			row_key: id.str()
		}
	}
}

// exec deletes the row, with its join table rows, in one transaction, or
// returns a `NotFoundError`.
pub fn (b BookDeleteOne) exec() ! {
	if !b.graph.client.delete_one(b.data)! {
		return NotFoundError{
			table: 'books'
		}
	}
}

// BookDelete builds the delete of the `books` rows that match its conditions.
// Start one with `Graph.books().delete()`.
pub struct BookDelete {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete starts the delete of the rows that match the query's conditions; its
// order, limit and offset don't apply.
pub fn (q BookQuery) delete() BookDelete {
	return BookDelete{
		graph: q.graph
		data:  vgraph.MutationData{
			op:    .delete
			table: 'books'
			conds: q.query.conds.clone()
		}
	}
}

// where keeps the rows that match every one of `conds`.
pub fn (b BookDelete) where(conds ...load.Cond) BookDelete {
	return BookDelete{
		...b
		data: b.data.with_conds(conds)
	}
}

