// books_by_keys returns the rows with the keys `keys`, in their order.
fn (g Graph) books_by_keys(keys []string) ![]BookNode {
	// as stored: no privacy rule or interceptor hides a row just written
	rows := Graph{
		client: g.client.bypass()
	}.books().where(load.in_keys('id', keys, .int)).all()!
	mut by_key := map[string]BookNode{}
	for row in rows {
		by_key[row.book.id.str()] = row
	}
	mut found := []BookNode{cap: keys.len}
	for key in keys {
		found << by_key[key] or {
			return NotFoundError{
				table: 'books'
			}
		}
	}
	return found
}

// CreateBookInput is what a create of a `books` row sets, as the GraphQL input
// `CreateBookInput` gives it: `none` and empty lists leave things as
// they are.
pub struct CreateBookInput {
pub mut:
	title      ?string
	year       ?int
	pages      ?int
	author_ids []int
}

// set_input sets what `input` gives: clears first, then values, then edges.
pub fn (b BookCreate) set_input(input CreateBookInput) BookCreate {
	mut next := b
	if v := input.title {
		next = next.set_title(v)
	}
	if v := input.year {
		next = next.set_year(v)
	}
	if v := input.pages {
		next = next.set_pages(v)
	}
	if input.author_ids.len > 0 {
		next = next.add_authors_ids(...input.author_ids)
	}
	return next
}

// UpdateBookInput is what a update of a `books` row sets, as the GraphQL input
// `UpdateBookInput` gives it: `none` and empty lists leave things as
// they are.
pub struct UpdateBookInput {
pub mut:
	title             ?string
	year              ?int
	pages             ?int
	add_author_ids    []int
	remove_author_ids []int
	clear_authors     bool
}

// set_input sets what `input` gives: clears first, then values, then edges.
pub fn (b BookUpdateOne) set_input(input UpdateBookInput) BookUpdateOne {
	mut next := b
	if input.clear_authors {
		next = next.clear_authors()
	}
	if v := input.title {
		next = next.set_title(v)
	}
	if v := input.year {
		next = next.set_year(v)
	}
	if v := input.pages {
		next = next.set_pages(v)
	}
	if input.add_author_ids.len > 0 {
		next = next.add_authors_ids(...input.add_author_ids)
	}
	if input.remove_author_ids.len > 0 {
		next = next.remove_authors_ids(...input.remove_author_ids)
	}
	return next
}
